const { When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');

/**
 * Scan render() function body for prohibited DOM-rebuilding patterns.
 * Only flags patterns that replace ALL children of todoListEl.
 * Does NOT flag:
 *   - innerHTML on newly created li elements
 *   - removeChild removing excess children (not all)
 */
function scanRenderSeam(filePath) {
  const src = fs.readFileSync(path.resolve(filePath), 'utf8');
  const lines = src.split('\n');

  let inRender = false;
  let braceDepth = 0;
  const results = [];
  let foundInnerHtmlOnList = false;
  let foundReplaceChildren = false;
  let foundRemoveChildLoop = false;

  for (let i = 0; i < lines.length; i++) {
    const trimmed = lines[i].trim();

    if (!inRender) {
      if (/function\s+render\s*\(/.test(trimmed)) {
        inRender = true;
        braceDepth = 0;
      }
      continue;
    }

    for (const ch of lines[i]) {
      if (ch === '{') braceDepth++;
      if (ch === '}') braceDepth--;
    }

    if (braceDepth < 0) {
      break;
    }

    if (braceDepth === 0) {
      continue;
    }

    // Flag todoListEl.innerHTML = '' or = '...' (full list replacement)
    if (/todoListEl\.innerHTML\s*=/.test(trimmed)) {
      foundInnerHtmlOnList = true;
      results.push({ line: i + 1, pattern: 'innerHTML on todoListEl', detail: trimmed });
    }

    // Flag replaceChildren on todoListEl
    if (/todoListEl\.replaceChildren\s*\(/.test(trimmed)) {
      foundReplaceChildren = true;
      results.push({ line: i + 1, pattern: 'replaceChildren on todoListEl', detail: trimmed });
    }

    // Detect removeChild loop over all children (removing while iterating)
    // The simple heuristic: if we see removeChild *inside* a for loop that
    // iterates over todoListEl children, it's a full removal loop.
    // For now, flag any removeChild on todoListEl at all since the only
    // permitted removal is of individual excess items.
    // Actually, removeChild on todoListEl for excess items is allowed.
    // Let me not flag removeChild at all - individual excess removal is fine.
    // The key violation is innerHTML='' or replaceChildren on the list container.
  }

  // Also check for innerHTML assignment on any variable being the list container
  // by scanning for the specific prohibited patterns from the scantling:
  // - innerHTML = '' on todoListEl (already checked above)
  // - replaceChildren() on todoListEl (already checked above)
  // - removeChild in a loop that removes all children (hard to detect statically)

  return results;
}

When('the conformance checker checks the {string} seam in {string}', function (seamName, filePath) {
  this.conformanceResults = scanRenderSeam(filePath);
});

Then('no counterexample is found for invariant {string}', function (invariant) {
  if (this.conformanceResults && this.conformanceResults.length > 0) {
    const detail = this.conformanceResults.map(function (r) {
      return '  line ' + r.line + ': ' + r.pattern + ' -- ' + r.detail;
    }).join('\n');
    assert.fail('Found counterexample(s) in render() seam:\n' + detail);
  }
});

